export type ChangeStatus = "Review" | "Kept" | "Reverted";

export type WorkspaceChange = {
  id: string;
  title: string;
  page: string;
  pullRequest: number;
  status: ChangeStatus;
  note?: string;
};

export const goal = "Signup conversion";

export const changes: WorkspaceChange[] = [
  {
    id: "pr-42",
    title: "Move primary CTA above the fold",
    page: "Pricing page",
    pullRequest: 42,
    status: "Review",
  },
  {
    id: "pr-41",
    title: "Pricing CTA improvement",
    page: "Pricing page",
    pullRequest: 41,
    status: "Kept",
    note: "+18.7% lift",
  },
  {
    id: "pr-38",
    title: "Longer signup form",
    page: "Signup",
    pullRequest: 38,
    status: "Reverted",
  },
];

export const reviewCount = changes.filter(
  (change) => change.status === "Review",
).length;

import type { ReactNode } from "react";

export function PageHeading({
  eyebrow,
  title,
  description,
  action,
}: {
  eyebrow: string;
  title: string;
  description: string;
  action?: ReactNode;
}) {
  return (
    <div className="flex flex-col gap-5 sm:flex-row sm:items-end sm:justify-between">
      <div>
        <p className="text-[11px] font-[650] tracking-[1.5px] text-muted-foreground uppercase">
          {eyebrow}
        </p>
        <h1 className="mt-2 font-display text-[2rem] leading-tight font-semibold tracking-tight md:text-4xl">
          {title}
        </h1>
        <p className="mt-2 text-sm leading-relaxed text-muted-foreground">
          {description}
        </p>
      </div>
      {action}
    </div>
  );
}

import type { ReactNode } from "react";

export function SectionTitle({
  title,
  meta,
  action,
}: {
  title: string;
  meta?: string;
  action?: ReactNode;
}) {
  return (
    <div className="flex items-baseline justify-between gap-4">
      <h2 className="font-display text-lg font-semibold">{title}</h2>
      {action ??
        (meta ? (
          <span className="text-xs text-muted-foreground">{meta}</span>
        ) : null)}
    </div>
  );
}

import { goal, reviewCount } from "@/components/dashboard/workspace";

const metrics = [
  {
    label: goal,
    value: "3.8%",
    detail: "↑ 18.7% from baseline",
    tone: "success" as const,
  },
  {
    label: "Visitors analyzed",
    value: "2,418",
    detail: "Last 14 days",
    tone: "muted" as const,
  },
  {
    label: "Changes to review",
    value: reviewCount.toString().padStart(2, "0"),
    detail: reviewCount ? "Your approval needed" : "All caught up",
    tone: "muted" as const,
  },
];

export function MetricsStrip() {
  return (
    <div className="grid divide-y divide-border border-y border-border sm:grid-cols-3 sm:divide-x sm:divide-y-0">
      {metrics.map((metric) => (
        <div key={metric.label} className="py-5 sm:px-6 sm:first:pl-0 sm:last:pr-0">
          <span className="text-xs text-muted-foreground">{metric.label}</span>
          <strong className="mt-1 block font-display text-3xl font-semibold tracking-tight">
            {metric.value}
          </strong>
          <small
            className={
              metric.tone === "success"
                ? "mt-1 block text-xs text-success"
                : "mt-1 block text-xs text-muted-foreground"
            }
          >
            {metric.detail}
          </small>
        </div>
      ))}
    </div>
  );
}

import { SectionTitle } from "@/components/dashboard/section-title";
import { goal } from "@/components/dashboard/workspace";

const series = [
  3.08, 3.12, 3.2, 3.18, 3.24, 3.3, 3.27, 3.36, 3.44, 3.5, 3.58, 3.66, 3.74,
  3.8,
];

const width = 640;
const height = 200;
const padX = 8;
const padY = 18;
const min = 2.9;
const max = 4.05;

function xFor(index: number) {
  return padX + (index / (series.length - 1)) * (width - padX * 2);
}

function yFor(value: number) {
  return padY + (1 - (value - min) / (max - min)) * (height - padY * 2);
}

const line = series
  .map((value, index) => {
    const command = index === 0 ? "M" : "L";
    return `${command} ${xFor(index).toFixed(2)} ${yFor(value).toFixed(2)}`;
  })
  .join(" ");

const area = `${line} L ${xFor(series.length - 1).toFixed(2)} ${height - padY} L ${xFor(0).toFixed(2)} ${height - padY} Z`;
const baselineY = yFor(3.2);
const endX = xFor(series.length - 1);
const endY = yFor(series[series.length - 1]);

export function ConversionChart() {
  return (
    <section>
      <SectionTitle title={goal} meta="Last 14 days" />
      <svg
        viewBox={`0 0 ${width} ${height}`}
        className="mt-4 h-52 w-full"
        role="img"
        aria-label="Signup conversion over the last 14 days, rising from 3.2% to 3.8%"
      >
        <line
          x1={padX}
          x2={width - padX}
          y1={baselineY}
          y2={baselineY}
          className="stroke-border"
          strokeDasharray="4 6"
        />
        <path d={area} className="fill-success/10" />
        <path
          d={line}
          fill="none"
          className="stroke-success"
          strokeWidth="2"
          strokeLinejoin="round"
          strokeLinecap="round"
        />
        <circle cx={endX} cy={endY} r="7" className="fill-success/15" />
        <circle cx={endX} cy={endY} r="3.5" className="fill-success" />
      </svg>
      <p className="mt-3 flex items-center gap-2 text-xs text-muted-foreground">
        <span className="size-1.5 rounded-full bg-success ring-4 ring-success/10" />
        Pricing CTA improvement kept · +18.7% lift
      </p>
    </section>
  );
}

import { Check, GitPullRequest, ScanLine, type LucideIcon } from "lucide-react";
import { SectionTitle } from "@/components/dashboard/section-title";
import { reviewCount } from "@/components/dashboard/workspace";
import { cn } from "@/lib/utils";

export function CurrentCycle({ paused }: { paused: boolean }) {
  const steps: {
    icon: LucideIcon;
    title: string;
    detail: string;
    state: "done" | "current" | "pending";
  }[] = [
    {
      icon: Check,
      title: "Visitor behavior analyzed",
      detail: "Pricing page · 2,418 sessions",
      state: "done",
    },
    {
      icon: Check,
      title: "Friction identified",
      detail: "Primary CTA below the fold",
      state: "done",
    },
    {
      icon: GitPullRequest,
      title: reviewCount ? "Fix ready for review" : "Review complete",
      detail: "Pull request #42",
      state: "current",
    },
    {
      icon: ScanLine,
      title: "Measure the result",
      detail: paused
        ? "Waiting for agent to resume"
        : "After the change goes live",
      state: "pending",
    },
  ];

  return (
    <section>
      <SectionTitle
        title="Current cycle"
        meta={paused ? "Paused" : "In progress"}
      />
      <ol className="mt-2">
        {steps.map((step) => (
          <li
            key={step.title}
            className={cn(
              "flex gap-3 border-b border-border py-3.5 last:border-b-0",
              step.state === "pending" && "text-muted-foreground",
            )}
          >
            <step.icon
              className={cn(
                "mt-0.5 size-4 shrink-0",
                step.state === "done" && "text-success",
                step.state === "current" && "text-foreground",
                step.state === "pending" && "text-muted-foreground",
              )}
            />
            <div>
              <p className="text-sm">{step.title}</p>
              <small className="text-xs text-muted-foreground">{step.detail}</small>
            </div>
          </li>
        ))}
      </ol>
    </section>
  );
}

import { Check, GitPullRequest, RotateCcw } from "lucide-react";
import { changes, type ChangeStatus } from "@/components/dashboard/workspace";
import { cn } from "@/lib/utils";

const statusIcon = {
  Review: GitPullRequest,
  Kept: Check,
  Reverted: RotateCcw,
} as const;

const statusClass: Record<ChangeStatus, string> = {
  Review: "text-signal",
  Kept: "text-success",
  Reverted: "text-muted-foreground",
};

export function ChangeList({ limit }: { limit?: number }) {
  const items = typeof limit === "number" ? changes.slice(0, limit) : changes;

  return (
    <ul className="mt-2">
      {items.map((change) => {
        const Icon = statusIcon[change.status];

        return (
          <li
            key={change.id}
            className="flex items-center gap-3 border-b border-border py-4"
          >
            <Icon className={cn("size-4 shrink-0", statusClass[change.status])} />
            <div className="min-w-0 flex-1">
              <p className="text-sm font-medium">{change.title}</p>
              <p className="text-xs text-muted-foreground">
                {change.page} · Pull request #{change.pullRequest}
                {change.note ? ` · ${change.note}` : ""}
              </p>
            </div>
            <span className={cn("text-xs", statusClass[change.status])}>
              {change.status}
            </span>
          </li>
        );
      })}
    </ul>
  );
}

"use client";

import { useState } from "react";
import { ArrowRight, Pause, Play } from "lucide-react";
import Link from "next/link";
import { ChangeList } from "@/components/dashboard/change-list";
import { ConversionChart } from "@/components/dashboard/conversion-chart";
import { CurrentCycle } from "@/components/dashboard/current-cycle";
import { MetricsStrip } from "@/components/dashboard/metrics-strip";
import { PageHeading } from "@/components/dashboard/page-heading";
import { SectionTitle } from "@/components/dashboard/section-title";
import { Button } from "@/components/ui/button";

export function DashboardOverview() {
  const [paused, setPaused] = useState(false);

  return (
    <main className="flex flex-1 flex-col gap-10 px-6 pt-2 pb-12 md:px-8">
      <PageHeading
        eyebrow="YOUR WEBSITE, MOVING FORWARD"
        title="A little better, every day."
        description="Here’s what your agent has been working on."
        action={
          <Button variant="outline" onClick={() => setPaused((value) => !value)}>
            {paused ? <Play /> : <Pause />}
            {paused ? "Resume agent" : "Pause agent"}
          </Button>
        }
      />
      <MetricsStrip />
      <div className="grid items-start gap-10 lg:grid-cols-[minmax(0,1.45fr)_minmax(16rem,0.8fr)] lg:gap-16">
        <ConversionChart />
        <CurrentCycle paused={paused} />
      </div>
      <section>
        <SectionTitle
          title="Recent changes"
          action={
            <Button
              variant="ghost"
              size="sm"
              nativeButton={false}
              render={<Link href="/dashboard/changes" />}
            >
              All changes
              <ArrowRight />
            </Button>
          }
        />
        <ChangeList limit={3} />
      </section>
    </main>
  );
}

import type { Metadata } from "next";
import { DashboardOverview } from "@/components/dashboard/overview";

const title = "Overview — Friction Fixer";
const description =
  "Follow your agent’s progress, conversion trends, and recent website improvements.";

export const metadata: Metadata = {
  title,
  description,
  openGraph: {
    title,
    description: "Your website improvements, at a glance.",
    type: "website",
  },
  twitter: {
    card: "summary_large_image",
    title,
    description: "Your website improvements, at a glance.",
  },
};

export default function Page() {
  return <DashboardOverview />;
}

